    };
    auto getB = [&](int i, int j) -> double {
        // op(B)(i,j)
        if (trB == 0) return B[j*N + i];      // B is NxK col-major
        else          return B[i*K + j];      // B is KxN col-major, B^T(i,j)=B(j,i)
